118: /**
119:  * Copies the validated app bundle into the staging directory. Mirrors
120:  * updater.cjs's installUpdate() copy semantics exactly (verbatimSymlinks so
121:  * relative framework symlinks are preserved rather than dereferenced, and
122:  * force:false/errorOnExist so a partial destination is never silently
123:  * merged into).
124:  *
125:  * Under Electron, .asar archives in Contents/Resources must be copied as
126:  * plain files to avoid 'Invalid package' errors. This function handles both
127:  * regular directories and .asar files identically.
128:  */
129: async function copyAppBundle(candidatePath, stagedAppPath) {
130:   await fs.promises.mkdir(path.dirname(stagedAppPath), { recursive: true });
131:   
132:   // Check if the source is a .asar file (Electron archives)
133:   const candidateStats = await fs.promises.stat(candidatePath);
134:   const isAsarFile = candidatePath.endsWith('.asar');
135:   
136:   if (isAsarFile) {
137:     // For .asar files, copy as plain bytes without any special handling
138:     // that might trigger Electron's package validation logic.
139:     await fs.promises.copyFile(candidatePath, stagedAppPath);
140:   } else {
141:     // For regular directories and non-.asar files, use cp with verbatim symlinks
142:     await fs.promises.cp(candidatePath, stagedAppPath, {
143:       recursive: true,
144:       force: false,
145:       errorOnExist: true,
146:       verbatimSymlinks: true,
147:     });
148:   }
149: }
