151: /**
152:  * Converts a verified remote manifest (v2, signed, from
153:  * electron/remote-update-manifest.cjs) into the local trusted candidate
154:  * manifest shape that electron/updater.cjs's readAndValidateManifest()
155:  * expects: version, builtAt, app name/path, and application-tree SHA-256,
156:  * with no other fields. appPath is always the constant PRODUCT_NAME rather
157:  * than trusting the remote manifest's own appPath field, so this conversion
158:  * cannot be tricked into pointing the local manifest anywhere else.
159:  */
160: function buildLocalManifestFromRemote(remoteManifest, appTreeSha256) {
161:   return {
162:     version: remoteManifest.version,
163:     buildId: remoteManifest.buildId,
164:     builtAt: remoteManifest.builtAt,
165:     platform: remoteManifest.platform,
166:     arch: remoteManifest.arch,
167:     appPath: PRODUCT_NAME,
168:     sha256: appTreeSha256,
169:   };
170: }
