172: async function writeJsonAtomic(filePath, data) {
173:   const dir = path.dirname(filePath);
174:   await fs.promises.mkdir(dir, { recursive: true });
175:   const tmpPath = path.join(dir, `.${path.basename(filePath)}.tmp-${crypto.randomUUID()}`);
176:   await fs.promises.writeFile(tmpPath, JSON.stringify(data, null, 2));
177:   await fs.promises.rename(tmpPath, filePath);
178: }
