180: /**
181:  * Full P2C workflow for one already-verified build:
182:  *   verified .dmg -> mounted read-only -> inspected -> exact app copied ->
183:  *   staged -> DMG detached.
184:  *
185:  * Layout produced under resolveUpdatesDirectory()/<buildId>/:
186:  *   update-manifest.json   the raw verified remote (v2) manifest, kept for
187:  *                           audit/diagnostics next to the already-verified
188:  *                           DMG (never modified by this function).
189:  *   staged/update-manifest.json  the converted local (v1) trusted manifest,
190:  *                           ready for a future handoff to
191:  *                           updater.cjs's readAndValidateManifest(stagedDir).
192:  *   staged/Hearth Control.app    the copied, validated application bundle.
193:  *
194:  * Never calls updater.cjs's installUpdate() and never writes outside the
195:  * controlled per-build directory.
196:  */
197: async function stageVerifiedUpdate({
198:   manifest,
199:   dmgPath,
200:   updatesDir,
201:   execFileFn,
202:   mountTimeoutMs,
203:   detachTimeoutMs,
204:   detachMaxAttempts,
205:   detachRetryDelayMs,
206:   delayFn,
207: } = {}) {
208:   if (!manifest || typeof manifest !== 'object') throw new Error('A verified remote manifest is required.');
209:   if (!isCleanBuildIdSegment(manifest.buildId)) throw new Error('Manifest buildId is invalid for staging.');
210:   if (!dmgPath || typeof dmgPath !== 'string') throw new Error('A verified DMG path is required.');
211: 
212:   const baseDir = resolveUpdatesDirectory({ updatesDir });
213:   const buildDir = path.join(baseDir, manifest.buildId);
214:   if (!isInside(baseDir, buildDir)) {
215:     throw new Error('Build directory would escape the trusted updates root.');
216:   }
217: 
218:   const mountPoint = path.join(buildDir, MOUNT_DIR_NAME);
219:   const stagedDir = path.join(buildDir, STAGED_DIR_NAME);
220:   const stagedAppPath = path.join(stagedDir, PRODUCT_NAME);
221: 
222:   // An old incomplete staged directory for this exact build is never trusted;
223:   // remove it (only within this controlled build directory) before starting.
224:   await fs.promises.rm(stagedDir, { recursive: true, force: true });
225: 
226:   let mounted = false;
227:   let stagingError = null;
228:   let stagingResult = null;
229: 
230:   try {
231:     await mountDmgReadOnly({ dmgPath, mountPoint, execFileFn, timeoutMs: mountTimeoutMs });
232:     mounted = true;
233: 
234:     const candidatePath = await validateAppCandidate(mountPoint);
235: 
236:     await copyAppBundle(candidatePath, stagedAppPath);
237: 
238:     const actualSha256 = await sha256Directory(stagedAppPath);
239:     if (typeof manifest.sha256 === 'string' && actualSha256 !== manifest.sha256.toLowerCase()) {
240:       throw new Error('Staged application tree checksum does not match the verified manifest.');
241:     }
242: 
243:     await writeJsonAtomic(path.join(stagedDir, MANIFEST_NAME), buildLocalManifestFromRemote(manifest, actualSha256));
244:     await writeJsonAtomic(path.join(buildDir, MANIFEST_NAME), manifest);
245: 
246:     stagingResult = {
247:       buildDir,
248:       mountPoint,
249:       stagedDir,
250:       stagedAppPath,
251:       localManifestPath: path.join(stagedDir, MANIFEST_NAME),
252:     };
253:   } catch (err) {
254:     stagingError = err;
255:   }
256: 
257:   if (stagingError) {
258:     // Staging itself failed: the staged candidate (if any partial state
259:     // exists) is never trusted, regardless of what happens to the mount.
260:     await fs.promises.rm(stagedDir, { recursive: true, force: true }).catch(() => {});
261:   }
262: 
263:   let detachError = null;
264:   if (mounted) {
265:     try {
266:       await detachDmg({
267:         mountPoint,
268:         execFileFn,
269:         timeoutMs: detachTimeoutMs,
270:         maxAttempts: detachMaxAttempts,
271:         retryDelayMs: detachRetryDelayMs,
272:         delayFn,
273:       });
274:     } catch (err) {
275:       detachError = err;
276:     }
277:     await fs.promises.rm(mountPoint, { recursive: true, force: true }).catch(() => {});
278:   }
279: 
280:   if (stagingError) {
281:     // The original staging failure is always primary. A detach failure on
282:     // top of it is reported, not hidden, but it must never replace or mask
283:     // the real cause -- attach it rather than throwing a different error.
284:     if (detachError) {
285:       stagingError.cleanupError = detachError;
286:       console.error('[remote-update-stager] Detach also failed while cleaning up after a staging error:', safeReason(detachError.message));
287:     }
288:     throw stagingError;
289:   }
290: 
291:   if (detachError) {
292:     // Staging itself succeeded, but the mounted volume could not be detached
293:     // even after every bounded retry (including the final forced attempt).
294:     // A mounted volume must never be left behind silently, and staging must
295:     // never report success while that is true -- fail closed: discard the
296:     // staged trusted-candidate state and surface the detach failure.
297:     await fs.promises.rm(stagedDir, { recursive: true, force: true }).catch(() => {});
298:     const failClosedErr = new Error(
299:       `Update image could not be detached after staging succeeded; the staged candidate has been discarded: ${safeReason(detachError.message)}`,
300:     );
301:     failClosedErr.cause = detachError;
302:     throw failClosedErr;
303:   }
304: 
305:   return stagingResult;
306: }
